/**
 * Every feature of the Trend quality card, the Most active card, the SMA terminal and the Settings page, with the day
 * it was added (the IST day its pull request was merged), the pull request, a link to it in the app and what it is
 * for. The What's new page (`/whats-new`) lists them, and `<NewTag id>` (components/ui/NewTag.tsx) marks a feature
 * "New" next to its control while it is recent.
 *
 * Adding a feature: add an entry here (the day it is built, its PR number once known) and put `<NewTag id="…" />`
 * next to its control. Display only; nothing in the trading code reads this.
 */

export type FeatureArea = "trend" | "active" | "terminal" | "settings";

export const AREAS: { id: FeatureArea; label: string; href: string; hint: string }[] = [
  { id: "trend", label: "Trend quality", href: "/scalp/#trend", hint: "Scalp page: which stocks trend cleanly, and the scans around it" },
  { id: "active", label: "Most active", href: "/scalp/#active", hint: "Scalp page: where the money and volume are now, and its tests" },
  { id: "terminal", label: "SMA terminal", href: "/terminal/", hint: "The bots' desk: chart, replays, backtests, trades" },
  { id: "settings", label: "Settings", href: "/settings/", hint: "How each bot enters, exits and stops, and the all-bots rules" },
];

export type Feature = {
  /** Stable key: the What's new anchor (#f-<id>) and `<NewTag id>`. */
  id: string;
  title: string;
  area: FeatureArea;
  /** The IST day it was added, YYYY-MM-DD. */
  added: string;
  /** Its pull request on GitHub, when there is one. */
  pr?: number;
  /** Where it is in the app (a link). */
  href: string;
  /** Where it is, in words. */
  where: string;
  /** What it is for, in plain words. */
  purpose: string;
};

