/** Today in IST, YYYY-MM-DD. */
export function istToday(now: Date = new Date()): string {
  return new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Kolkata", year: "numeric", month: "2-digit", day: "2-digit" }).format(now);
}

/** Whole days from `added` to `today` (both YYYY-MM-DD). */
export function daysSince(added: string, today: string): number {
  const a = Date.parse(`${added}T00:00:00Z`);
  const b = Date.parse(`${today}T00:00:00Z`);
  return Math.round((b - a) / 86_400_000);
}

/** New = added within the last `days` days (today counts as day 1). */
export function isNew(feature: Pick<Feature, "added">, days: number, today: string = istToday()): boolean {
  const age = daysSince(feature.added, today);
  return age >= 0 && age < days;
}

const BY_ID = new Map(FEATURES.map((f) => [f.id, f]));

export function featureById(id: string): Feature | undefined {
  return BY_ID.get(id);
}

/** Strategy-form parts with their own anchor, and the numbered group (`#sma-<group>`) each sits in. */
const ANCHOR_GROUP: Record<string, string> = {
  "sma-candle-interval": "enter", "sma-day-extreme": "enter", "sma-colour-exit": "enter", "sma-colour-force": "enter",
  "sma-fresh": "check", "sma-exit-candle": "exit", "sma-slope-candle": "exit", "sma-small-colour": "exit",
  "sma-slope-editor": "exit", "sma-atr-target": "stop", "sma-smart-stop": "stop", "sma-fade-unarm": "advanced",
};

/** The strategy form's group (enter, check, exit, gap, stop, risk, advanced) a Settings link opens, or null. */
export function strategyGroupOf(href: string): string | null {
  if (!href.startsWith("/settings")) return null;
  const anchor = href.split("#")[1] ?? "";
  if (!anchor.startsWith("sma-")) return null;
  return ANCHOR_GROUP[anchor] ?? anchor.slice(4);
}

/** The choices for "New = added in the last N days". */
export const NEW_DAY_CHOICES = [1, 3, 7, 14, 30] as const;
export const DEFAULT_NEW_DAYS = 7;
